def print_version():
    print(VERSION)
    sys.exit(0)

def print_help(text):
    sys.stdout.write(text)
    if not text.endswith("\n"):
        sys.stdout.write("\n")
    sys.exit(0)

def error_and_exit(message, usage=None, exit_code=2):
    sys.stderr.write(f"error: {message}\n")
    if usage:
        sys.stderr.write("\n")
        sys.stderr.write(f"{usage}\n")
        sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(exit_code)

def use_color_mode(mode):
    if mode == "always":
        return True
    if mode == "never":
        return False
    return sys.stdout.isatty()

def use_color_stderr(mode):
    if mode == "always":
        return True
    if mode == "never":
        return False
    return sys.stderr.isatty()

def colorize(text, code, enable):
    if not enable:
        return text
    return f"\x1b[{code}m{text}\x1b[0m"

def grey(text, enable):
    return colorize(text, "38;5;8", enable)

def green(text, enable):
    return colorize(text, "32", enable)

def red(text, enable):
    return colorize(text, "31", enable)

def red_bold(text, enable):
    return colorize(text, "1;31", enable)

def bold(text, enable):
    return colorize(text, "1", enable)

def header_print(dry_run, silent, color_mode):
    if silent or not dry_run:
        return
    enable = use_color_mode(color_mode)
    msg = "This is a DRY-RUN"
    if enable:
        sys.stdout.write(f"\x1b[1m{msg}\x1b[0m\n"); sys.stdout.flush()
    else:
        sys.stdout.write(f"{msg}\n"); sys.stdout.flush()

def print_backup_info(src, silent, color_mode):
    if silent:
        return
    enable = use_color_mode(color_mode)
    bk = src + ".bk"
    if enable:
        sys.stdout.write(f"\x1b[1mInfo: \x1b[0m Backup created - {grey(f'{src} -> {bk}', enable)}\n"); sys.stdout.flush()
    else:
        sys.stdout.write(f"Info:  Backup created - {src} -> {bk}\n"); sys.stdout.flush()

def print_operation(src, dst, silent, color_mode):
    if silent:
        return
    enable = use_color_mode(color_mode)
    if not enable:
        sys.stdout.write(f"{src} -> {dst}\n"); sys.stdout.flush()
        return
    src_dir = os.path.dirname(src)
    src_base = os.path.basename(src)
    dst_dir = os.path.dirname(dst)
    dst_base = os.path.basename(dst)
    if src_dir:
        src_dir_slash = src_dir + "/"
    else:
        src_dir_slash = ""
    if dst_dir:
        dst_dir_slash = dst_dir + "/"
    else:
        dst_dir_slash = ""
    src_colored = grey(src_dir_slash, enable) + grey(src_base, enable)
    prefix_len = 0
    min_len = min(len(src_base), len(dst_base))
    for i in range(min_len):
        if src_base[i] == dst_base[i]:
            prefix_len += 1
        else:
            break
    suffix_len = 0
    for i in range(1, min_len - prefix_len + 1):
        if src_base[-i] == dst_base[-i]:
            suffix_len += 1
        else:
            break
    if prefix_len + suffix_len > len(dst_base):
        suffix_len = len(dst_base) - prefix_len
        if suffix_len < 0:
            suffix_len = 0
    prefix = dst_base[:prefix_len] if prefix_len else ""
    middle = dst_base[prefix_len: len(dst_base)-suffix_len if suffix_len else len(dst_base)]
    suffix = dst_base[len(dst_base)-suffix_len:] if suffix_len else ""
    dst_colored = green(dst_dir_slash, enable)
    if prefix:
        dst_colored += green(prefix, enable)
    if middle:
        dst_colored += red_bold(middle, enable)
    if suffix:
        dst_colored += green(suffix, enable)
    sys.stdout.write(f"{src_colored} -> {dst_colored}\n"); sys.stdout.flush()

def print_error(msg, color_mode, silent, is_stdout=False):
    if silent:
        return
    enable = use_color_stderr(color_mode) if not is_stdout else use_color_mode(color_mode)
    if enable:
        sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
