def ascii_transliterate(s):
    mapping = {
        'ß': 'ss',
        'Æ': 'AE',
        'æ': 'ae',
        'Ø': 'O',
        'ø': 'o',
        'Å': 'A',
        'å': 'a',
        'Œ': 'OE',
        'œ': 'oe',
        'Ð': 'D',
        'ð': 'd',
        'Þ': 'TH',
        'þ': 'th',
        'Ł': 'L',
        'ł': 'l',
    }
    for k,v in mapping.items():
        s = s.replace(k, v)
    nfkd = unicodedata.normalize('NFKD', s)
    ascii_bytes = nfkd.encode('ascii', 'ignore')
    return ascii_bytes.decode('ascii')

def is_hidden_path(path):
    base = os.path.basename(path.rstrip("/"))
    return base.startswith(".") and base not in (".", "..")

def collect_candidates(paths, recursive, include_dirs, hidden, max_depth):
    candidates = []
    for p in paths:
        original = p
        if not os.path.lexists(p):
            continue
        is_link = os.path.islink(p)
        if is_link:
            candidates.append(p)
            continue
        if os.path.isfile(p):
            candidates.append(p)
            continue
        is_dir = os.path.isdir(p)
        if is_dir:
            if not recursive:
                if include_dirs:
                    candidates.append(p)
                else:
                    pass
            else:
                if include_dirs:
                    candidates.append(p)
                start = p
                stack = [(start, 0)]
                while stack:
                    cur_dir, cur_depth = stack.pop()
                    try:
                        with os.scandir(cur_dir) as it:
                            entries = list(it)
                    except:
                        continue
                    entries.sort(key=lambda e: e.name)
                    dirs_to_push = []
                    for entry in entries:
                        name = entry.name
                        entry_path = entry.path
                        if not hidden and name.startswith('.'):
                            continue
                        entry_depth = cur_depth + 1
                        if max_depth is not None and entry_depth > max_depth:
                            continue
                        try:
                            is_entry_dir = entry.is_dir(follow_symlinks=False)
                            is_entry_symlink = entry.is_symlink()
                        except:
                            continue
                        if is_entry_symlink:
                            candidates.append(entry_path)
                        elif is_entry_dir:
                            if include_dirs:
                                candidates.append(entry_path)
                            dirs_to_push.append((entry_path, entry_depth))
                        else:
                            candidates.append(entry_path)
                    for d in reversed(dirs_to_push):
                        stack.append(d)
            continue
    return candidates

def expand_replacement(match, repl):
    res = []
    i = 0
    n = len(repl)
    while i < n:
        c = repl[i]
        if c == '$':
            if i+1 < n and repl[i+1] == '$':
                res.append('$')
                i += 2
                continue
            elif i+1 < n and repl[i+1] == '{':
                j = repl.find('}', i+2)
                if j == -1:
                    res.append('$')
                    i += 1
                    continue
                name = repl[i+2:j]
                if name.isdigit():
                    try:
                        g = match.group(int(name))
                        if g is None:
                            g = ''
                        res.append(g)
                    except:
                        res.append('')
                else:
                    try:
                        g = match.group(name)
                        if g is None:
                            g = ''
                        res.append(g)
                    except:
                        res.append('')
                i = j + 1
                continue
            elif i+1 < n and repl[i+1].isdigit():
                j = i+1
                while j < n and repl[j].isdigit():
                    j+=1
                num_str = repl[i+1:j]
                try:
                    g = match.group(int(num_str))
                    if g is None:
                        g = ''
                    res.append(g)
                except:
                    res.append('')
                i = j
                continue
            elif i+1 < n and (repl[i+1].isalpha() or repl[i+1] == '_'):
                j = i+1
                while j < n and (repl[j].isalnum() or repl[j] == '_'):
                    j+=1
                name = repl[i+1:j]
                try:
                    g = match.group(name)
                    if g is None:
                        g = ''
                    res.append(g)
                except:
                    res.append('')
                i = j
                continue
            else:
                res.append('$')
                i += 1
                continue
        else:
            res.append(c)
            i += 1
    return ''.join(res)

def regex_replace(text, pattern, repl, limit, transform):
    if limit == 0:
        result = []
        last_end = 0
        for m in pattern.finditer(text):
            result.append(text[last_end:m.start()])
            expanded = expand_replacement(m, repl)
            if transform:
                if transform == "upper":
                    expanded = expanded.upper()
                elif transform == "lower":
                    expanded = expanded.lower()
                elif transform == "ascii":
                    expanded = ascii_transliterate(expanded)
            result.append(expanded)
            last_end = m.end()
            if m.start() == m.end():
                if last_end < len(text):
                    result.append(text[last_end])
                    last_end += 1
                else:
                    break
        result.append(text[last_end:])
        return ''.join(result)
    else:
        result = []
        last_end = 0
        count = 0
        for m in pattern.finditer(text):
            if count >= limit:
                break
            result.append(text[last_end:m.start()])
            expanded = expand_replacement(m, repl)
            if transform:
                if transform == "upper":
                    expanded = expanded.upper()
                elif transform == "lower":
                    expanded = expanded.lower()
                elif transform == "ascii":
                    expanded = ascii_transliterate(expanded)
            result.append(expanded)
            last_end = m.end()
            count += 1
            if m.start() == m.end():
                if last_end < len(text):
                    result.append(text[last_end])
                    last_end += 1
                else:
                    break
        result.append(text[last_end:])
        return ''.join(result)

def handle_regex(args, color_mode, dry_run, backup, silent, dump_flag, no_dump_flag, dump_prefix, replace_limit, replace_transform, include_dirs, recursive, max_depth, hidden):
    if max_depth is not None and not recursive:
