            should_dump = True
    if should_dump and operations:
        prefix = dump_prefix if dump_prefix else "rnr-"
        now = datetime.datetime.now()
        date_str = now.strftime("%Y-%m-%d %H:%M:%S")
        file_date = now.strftime("%Y-%m-%d_%H%M%S")
        filename = f"{prefix}{file_date}.json"
        data = {"date": date_str, "operations": [{"source": s, "target": t} for s,t in operations]}
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
                f.write("\n")
        except:
            if not silent:
                sys.stderr.write(f"Error: Cannot write dump file {filename}\n"); sys.stderr.flush()
            sys.exit(1)
    sys.exit(0)

def handle_from_file(dumpfile, color_mode, dry_run, backup, silent, dump_flag, no_dump_flag, dump_prefix, undo_flag):
    header_print(dry_run, silent, color_mode)
    if not os.path.exists(dumpfile):
        if not silent:
            enable = use_color_stderr(color_mode)
            msg = f"Cannot open/read file {dumpfile}"
            if enable:
                sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
            else:
                sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
        sys.exit(1)
    try:
        with open(dumpfile, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        if not silent:
            enable = use_color_stderr(color_mode)
            msg = f"Cannot parse JSON file {dumpfile}"
            if enable:
                sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
            else:
                sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
        sys.exit(1)
    try:
        ops = data["operations"]
        operations = []
        for op in ops:
            src = op["source"]
            tgt = op["target"]
            if undo_flag:
                operations.append((tgt, src))
            else:
                operations.append((src, tgt))
    except:
        if not silent:
            enable = use_color_stderr(color_mode)
            msg = f"Cannot parse JSON file {dumpfile}"
            if enable:
                sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
            else:
                sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
        sys.exit(1)
    target_counts = {}
    for src,dst in operations:
        target_counts[dst] = target_counts.get(dst,0)+1
    duplicates = [dst for dst,cnt in target_counts.items() if cnt>1]
    if duplicates:
        if not silent:
            enable = use_color_stderr(color_mode)
            if enable:
                sys.stderr.write(f"\x1b[31mError: \x1b[0mFiles will have the same name\n\n"); sys.stderr.flush()
                for src,dst in operations:
                    if dst in duplicates:
                        sys.stderr.write(f"{src}->{dst}\n"); sys.stderr.flush()
                sys.stderr.write("\n"); sys.stderr.flush()
            else:
                sys.stderr.write(f"Error: Files will have the same name\n\n"); sys.stderr.flush()
                for src,dst in operations:
                    if dst in duplicates:
                        sys.stderr.write(f"{src}->{dst}\n"); sys.stderr.flush()
                sys.stderr.write("\n"); sys.stderr.flush()
        sys.exit(1)
    for src,dst in operations:
        if os.path.lexists(dst):
            if not silent:
                enable = use_color_stderr(color_mode)
                msg = f"Conflict with existing path {src} -> {dst}"
                if enable:
                    sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
                else:
                    sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
            sys.exit(1)
    if not operations:
        sys.exit(0)
    if backup and not dry_run:
        for src,dst in operations:
            if os.path.isdir(src) and not os.path.islink(src):
                continue
            bk = src + ".bk"
            try:
                shutil.copy2(src, bk)
                print_backup_info(src, silent, color_mode)
            except Exception as e:
                if not silent:
                    enable = use_color_stderr(color_mode)
                    msg = f"Cannot create a backup of {src}"
                    if enable:
                        sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
                    else:
                        sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
                sys.exit(1)
    for src,dst in operations:
        print_operation(src,dst,silent,color_mode)
    if not dry_run:
        for src,dst in operations:
            try:
                os.rename(src, dst)
            except OSError as e:
                if not silent:
                    enable = use_color_stderr(color_mode)
                    msg = f"Cannot rename {src} -> {dst}\n{e.strerror} (os error {e.errno})"
                    if enable:
                        sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
                    else:
                        sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
                sys.exit(1)
    should_dump = False
    if dry_run:
        if dump_flag:
            should_dump = True
    else:
        if not no_dump_flag:
            should_dump = True
    if should_dump and operations:
        prefix = dump_prefix if dump_prefix else "rnr-"
        now = datetime.datetime.now()
        date_str = now.strftime("%Y-%m-%d %H:%M:%S")
        file_date = now.strftime("%Y-%m-%d_%H%M%S")
        filename = f"{prefix}{file_date}.json"
        data = {"date": date_str, "operations": [{"source": s, "target": t} for s,t in operations]}
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
                f.write("\n")
        except:
            if not silent:
                sys.stderr.write(f"Error: Cannot write dump file {filename}\n"); sys.stderr.flush()
            sys.exit(1)
    sys.exit(0)

