    if argv[1] == "help":
        if len(argv) == 2:
            print_help(TOP_HELP)
        elif argv[2] == "regex":
            print_help(REGEX_HELP)
        elif argv[2] == "from-file":
            print_help(FROM_FILE_HELP)
        elif argv[2] == "to-ascii":
            print_help(TO_ASCII_HELP)
        else:
            sys.stderr.write(f"error: unrecognized subcommand '{argv[2]}'\n\nUsage: executable <COMMAND>\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
            sys.exit(2)
    sub = argv[1]
    if sub not in ("regex", "from-file", "to-ascii"):
        sys.stderr.write(f"error: unrecognized subcommand '{sub}'\n\nUsage: executable <COMMAND>\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
        sys.exit(2)
    tokens = argv[2:]
    if "--help" in tokens or "-h" in tokens:
        if sub == "regex":
            print_help(REGEX_HELP)
        elif sub == "from-file":
            print_help(FROM_FILE_HELP)
        elif sub == "to-ascii":
