    min_len = min(len(src_base), len(dst_base))
    for i in range(min_len):
        if src_base[i] == dst_base[i]:
            prefix_len += 1
        else:
            break
    suffix_len = 0
    for i in range(1, min_len - prefix_len + 1):
        if src_base[-i] == dst_base[-i]:
            suffix_len += 1
        else:
