                    j+=1
                num_str = repl[i+1:j]
                try:
                    g = match.group(int(num_str))
                    if g is None:
                        g = ''
                    res.append(g)
                except:
                    res.append('')
                i = j
                continue
            elif i+1 < n and (repl[i+1].isalpha() or repl[i+1] == '_'):
                j = i+1
                while j < n and (repl[j].isalnum() or repl[j] == '_'):
                    j+=1
                name = repl[i+1:j]
                try:
                    g = match.group(name)
                    if g is None:
                        g = ''
                    res.append(g)
                except:
                    res.append('')
                i = j
                continue
            else:
                res.append('$')
                i += 1
                continue
        else:
            res.append(c)
            i += 1
    return ''.join(res)

def regex_replace(text, pattern, repl, limit, transform):
    if limit == 0:
        result = []
        last_end = 0
        for m in pattern.finditer(text):
            result.append(text[last_end:m.start()])
            expanded = expand_replacement(m, repl)
            if transform:
                if transform == "upper":
                    expanded = expanded.upper()
                elif transform == "lower":
                    expanded = expanded.lower()
                elif transform == "ascii":
                    expanded = ascii_transliterate(expanded)
            result.append(expanded)
            last_end = m.end()
            if m.start() == m.end():
                if last_end < len(text):
                    result.append(text[last_end])
                    last_end += 1
                else:
                    break
        result.append(text[last_end:])
        return ''.join(result)
    else:
        result = []
        last_end = 0
        count = 0
        for m in pattern.finditer(text):
            if count >= limit:
                break
            result.append(text[last_end:m.start()])
            expanded = expand_replacement(m, repl)
            if transform:
                if transform == "upper":
                    expanded = expanded.upper()
                elif transform == "lower":
                    expanded = expanded.lower()
                elif transform == "ascii":
                    expanded = ascii_transliterate(expanded)
            result.append(expanded)
            last_end = m.end()
            count += 1
            if m.start() == m.end():
                if last_end < len(text):
                    result.append(text[last_end])
                    last_end += 1
                else:
                    break
        result.append(text[last_end:])
        return ''.join(result)

def handle_regex(args, color_mode, dry_run, backup, silent, dump_flag, no_dump_flag, dump_prefix, replace_limit, replace_transform, include_dirs, recursive, max_depth, hidden):
    if max_depth is not None and not recursive:
        sys.stderr.write("error: the following required arguments were not provided:\n  --recursive\n\nUsage: executable regex --recursive --no-dump --color <COLOR> --max-depth <LEVEL> <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
        sys.exit(2)
    if len(args) < 3:
        if len(args) == 0:
            sys.stderr.write("error: the following required arguments were not provided:\n  <EXPRESSION>\n  <REPLACEMENT>\n  <PATH(S)>...\n\nUsage: executable regex <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
            sys.exit(2)
        elif len(args) == 1:
            sys.stderr.write("error: the following required arguments were not provided:\n  <REPLACEMENT>\n  <PATH(S)>...\n\nUsage: executable regex <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
            sys.exit(2)
        elif len(args) == 2:
            sys.stderr.write("error: the following required arguments were not provided:\n  <PATH(S)>...\n\nUsage: executable regex <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
            sys.exit(2)
    expression = args[0]
    replacement = args[1]
    paths = args[2:]
    try:
        pattern = re.compile(expression)
    except re.error as e:
        msg = str(e)
        if "unterminated character set" in msg:
            msg = "unclosed character class"
        elif "missing ), unterminated subpattern" in msg:
            msg = "unclosed group"
        if not silent:
            enable = use_color_stderr(color_mode)
            header = "Bad expression provided"
            if enable:
                sys.stderr.write(f"\x1b[31mError: \x1b[0m{header}\n\n"); sys.stderr.flush()
                sys.stderr.write(f"regex parse error:\n    {expression}\n    ^\nerror: {msg}\n"); sys.stderr.flush()
            else:
                sys.stderr.write(f"Error: {header}\n\nregex parse error:\n    {expression}\n    ^\nerror: {msg}\n"); sys.stderr.flush()
        sys.exit(1)
    candidates = collect_candidates(paths, recursive, include_dirs, hidden, max_depth)
    operations = []
    for cand in candidates:
        dir_part = os.path.dirname(cand)
        base = os.path.basename(cand.rstrip("/"))
        new_base = regex_replace(base, pattern, replacement, replace_limit, replace_transform)
        if new_base == base:
            continue
        if dir_part:
            target = os.path.join(dir_part, new_base)
        else:
            target = new_base
        operations.append((cand, target))
    header_print(dry_run, silent, color_mode)
    target_counts = {}
    for src, dst in operations:
        target_counts[dst] = target_counts.get(dst, 0) + 1
    duplicates = [dst for dst, cnt in target_counts.items() if cnt > 1]
    if duplicates:
        if not silent:
            enable = use_color_stderr(color_mode)
            if enable:
                sys.stderr.write(f"\x1b[31mError: \x1b[0mFiles will have the same name\n\n"); sys.stderr.flush()
                for src, dst in operations:
                    if dst in duplicates:
                        sys.stderr.write(f"{src}->{dst}\n"); sys.stderr.flush()
                sys.stderr.write("\n"); sys.stderr.flush()
            else:
                sys.stderr.write(f"Error: Files will have the same name\n\n"); sys.stderr.flush()
                for src, dst in operations:
                    if dst in duplicates:
                        sys.stderr.write(f"{src}->{dst}\n"); sys.stderr.flush()
                sys.stderr.write("\n"); sys.stderr.flush()
        sys.exit(1)
    for src, dst in operations:
        if os.path.lexists(dst):
            if not silent:
                enable = use_color_stderr(color_mode)
                msg = f"Conflict with existing path {src} -> {dst}"
                if enable:
                    sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
                else:
                    sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
            sys.exit(1)
    if not operations:
        sys.exit(0)
    if backup:
        if not dry_run:
            for src, dst in operations:
                if os.path.isdir(src) and not os.path.islink(src):
                    continue
                bk = src + ".bk"
                try:
                    shutil.copy2(src, bk)
                    print_backup_info(src, silent, color_mode)
                except Exception as e:
                    if not silent:
                        enable = use_color_stderr(color_mode)
                        msg = f"Cannot create a backup of {src}"
                        if enable:
                            sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
                        else:
                            sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
                    sys.exit(1)
    for src, dst in operations:
        print_operation(src, dst, silent, color_mode)
    if not dry_run:
        for src, dst in operations:
            try:
                os.rename(src, dst)
            except OSError as e:
                if not silent:
                    enable = use_color_stderr(color_mode)
                    msg = f"Cannot rename {src} -> {dst}\n{e.strerror} (os error {e.errno})"
                    if enable:
                        sys.stderr.write(f"\x1b[31mError: \x1b[0m{msg}\n"); sys.stderr.flush()
                    else:
                        sys.stderr.write(f"Error: {msg}\n"); sys.stderr.flush()
                sys.exit(1)
    should_dump = False
    if dry_run:
        if dump_flag:
            should_dump = True
    else:
        if not no_dump_flag:
            should_dump = True
    if should_dump and operations:
        prefix = dump_prefix if dump_prefix else "rnr-"
        now = datetime.datetime.now()
        date_str = now.strftime("%Y-%m-%d %H:%M:%S")
        file_date = now.strftime("%Y-%m-%d_%H%M%S")
        filename = f"{prefix}{file_date}.json"
        data = {"date": date_str, "operations": [{"source": s, "target": t} for s,t in operations]}
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2)
                f.write("\n")
        except Exception as e:
            if not silent:
                sys.stderr.write(f"Error: Cannot write dump file {filename}\n"); sys.stderr.flush()
            sys.exit(1)
    sys.exit(0)

