def parse_and_dispatch():
    argv = sys.argv
    if len(argv) == 1:
        sys.stdout.write(TOP_HELP)
        sys.exit(0)
    if argv[1] in ("--version", "-V"):
        print_version()
    if argv[1] in ("--help", "-h"):
        print_help(TOP_HELP)
    if argv[1] == "help":
        if len(argv) == 2:
            print_help(TOP_HELP)
        elif argv[2] == "regex":
            print_help(REGEX_HELP)
        elif argv[2] == "from-file":
            print_help(FROM_FILE_HELP)
        elif argv[2] == "to-ascii":
            print_help(TO_ASCII_HELP)
        else:
            sys.stderr.write(f"error: unrecognized subcommand '{argv[2]}'\n\nUsage: executable <COMMAND>\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
            sys.exit(2)
    sub = argv[1]
    if sub not in ("regex", "from-file", "to-ascii"):
        sys.stderr.write(f"error: unrecognized subcommand '{sub}'\n\nUsage: executable <COMMAND>\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
        sys.exit(2)
    tokens = argv[2:]
    if "--help" in tokens or "-h" in tokens:
        if sub == "regex":
            print_help(REGEX_HELP)
        elif sub == "from-file":
            print_help(FROM_FILE_HELP)
        elif sub == "to-ascii":
            print_help(TO_ASCII_HELP)
    if sub == "regex":
        dry_run = None
        force = None
        backup = False
        silent = False
        color = "auto"
        dump_flag = False
        no_dump_flag = False
        dump_prefix = "rnr-"
        dump_prefix_set = False
        replace_limit = 1
        replace_limit_set = False
        replace_transform = None
        include_dirs = False
        recursive = False
        max_depth = None
        hidden = False
        positional = []
        i = 0
        stop_options = False
        while i < len(tokens):
            tok = tokens[i]
            if stop_options:
                positional.append(tok)
                i+=1
                continue
            if tok == "--":
                stop_options = True
                i+=1
                continue
            if tok.startswith("--"):
                if tok == "--dry-run":
                    if force:
                        sys.stderr.write("error: the argument '--dry-run' cannot be used with '--force'\n\nUsage: executable regex --dry-run --no-dump --color <COLOR> <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                        sys.exit(2)
                    dry_run = True
                    i+=1
                elif tok == "--force":
                    if dry_run:
                        sys.stderr.write("error: the argument '--dry-run' cannot be used with '--force'\n\nUsage: executable regex [OPTIONS] <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                        sys.exit(2)
                    force = True
                    i+=1
                elif tok == "--backup":
                    backup = True
                    i+=1
                elif tok == "--silent":
                    silent = True
                    i+=1
                elif tok.startswith("--color"):
                    val = None
                    if "=" in tok:
                        _, val = tok.split("=",1)
                    else:
                        if i+1 >= len(tokens):
                            sys.stderr.write("error: a value is required for '--color <COLOR>' but none was supplied\n  [possible values: always, never, auto]\n\nUsage: executable regex [OPTIONS] <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                            sys.exit(2)
                        val = tokens[i+1]
                        i+=1
                    if val not in ("always","never","auto"):
                        sys.stderr.write(f"error: invalid value '{val}' for '--color <COLOR>'\n  [possible values: always, never, auto]\n\nUsage: executable regex [OPTIONS] <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                        sys.exit(2)
                    color = val
                    i+=1
                elif tok == "--dump":
                    if no_dump_flag:
                        sys.stderr.write("error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: executable regex --dump --color <COLOR> <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                        sys.exit(2)
                    dump_flag = True
                    i+=1
                elif tok == "--no-dump":
                    if dump_flag:
                        sys.stderr.write("error: the argument '--dump' cannot be used with '--no-dump'\n\nUsage: executable regex --dump --color <COLOR> <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                        sys.exit(2)
                    if dump_prefix_set:
                        sys.stderr.write("error: the argument '--dump-prefix <DUMP_PREFIX>' cannot be used with '--no-dump'\n\nUsage: executable regex --no-dump --color <COLOR> <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                        sys.exit(2)
                    no_dump_flag = True
                    i+=1
                elif tok.startswith("--dump-prefix"):
                    val = None
                    if "=" in tok:
                        _, val = tok.split("=",1)
                    else:
                        if i+1 >= len(tokens):
                            sys.stderr.write("error: a value is required for '--dump-prefix <DUMP_PREFIX>' but none was supplied\n\nUsage: executable regex [OPTIONS] <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n"); sys.stderr.flush()
                            sys.exit(2)
                        val = tokens[i+1]
